const carouselDots = document.getElementById('carouselDots');
const slides = carouselTrack.children;
const slideData = [
  { title: 'Studio Action', desc: 'Intense sessions in the Red Room' },
  { title: 'Community Events', desc: 'The pack that trains together' },
  { title: 'Post-Workout Moments', desc: 'Earned. Every single rep.' },
  { title: 'Branded Apparel', desc: 'Wear the hustle' }
];
let currentSlide = 0;
const totalSlides = slides.length;

// Build dots
for (let i = 0; i < totalSlides; i++) {
  const dot = document.createElement('button');
  dot.className = 'carousel-dot' + (i === 0 ? ' active' : '');
  dot.setAttribute('aria-label', 'Go to slide ' + (i + 1));
  dot.onclick = () => goToSlide(i);
  carouselDots.appendChild(dot);
}

function updateCarousel() {
  carouselTrack.style.transform = 'translateX(-' + (currentSlide * 100) + '%)';
  document.querySelectorAll('.carousel-dot').forEach((d, i) => {
    d.classList.toggle('active', i === currentSlide);
  });
  document.getElementById('carouselTitle').textContent = slideData[currentSlide].title;
  document.getElementById('carouselDesc').textContent = slideData[currentSlide].desc;
}

function moveCarousel(dir) {
  currentSlide = (currentSlide + dir + totalSlides) % totalSlides;
  updateCarousel();
}

function goToSlide(index) {
  currentSlide = index;
  updateCarousel();
}

