function switchToggle(mode) {
  const btnFloor = document.getElementById('btnFloor');
  const btnTread = document.getElementById('btnTread');
  const floorContent = document.getElementById('floorContent');
  const treadContent = document.getElementById('treadContent');

  if (mode === 'floor') {
    btnFloor.classList.add('active');
    btnTread.classList.remove('active');
    floorContent.classList.remove('hidden');
    treadContent.classList.add('hidden');
  } else {
    btnTread.classList.add('active');
    btnFloor.classList.remove('active');
    treadContent.classList.remove('hidden');
    floorContent.classList.add('hidden');
  }
}

function handleNewsletter(e) {
  e.preventDefault();
  const input = document.getElementById('newsletterEmail');
  const msg = document.getElementById('newsletterMsg');
  const email = input.value.trim();
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  input.classList.remove('error');
  msg.className = 'newsletter-msg';
  msg.textContent = '';

  if (!email) {
    input.classList.add('error');
    msg.className = 'newsletter-msg error';
    msg.textContent = 'Please enter an email address.';
    return;
  }
  if (!emailRegex.test(email)) {
    input.classList.add('error');
    msg.className = 'newsletter-msg error';
    msg.textContent = 'Please enter a valid email address.';
    return;
  }

  msg.className = 'newsletter-msg success';
  msg.textContent = "You're in! Check your inbox for a confirmation.";
  input.value = '';
}
